/// <summary>
///    AVA <c>Clicked</c> class.
/// </summary>
public void clicked()
{
    Args            locArgs;
    FormDataSource  locFormDataSource;
    SalesTable      locSalesTable;

    locArgs             = new Args();
    locFormDataSource   = element.SalesTable_DS;
    locSalesTable       = locFormDataSource.cursor();
    locArgs.caller(element);
    locArgs.record(locSalesTable);
    SalesTable::avaItemSetExpandPossiblePositions(locArgs, locSalesTable.SalesId);

    next clicked();

    locFormDataSource.research(true);
    locFormDataSource.refresh();
}
